from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
def crop(name,x1,y1,x2,y2,s=4.0):
    c = im.crop((x1,y1,x2,y2)).resize((int((x2-x1)*s), int((y2-y1)*s)))
    d = ImageDraw.Draw(c); W,H=c.size
    for i in range(1,20):
        d.line([(W*i/20,0),(W*i/20,H)],fill=(255,0,0),width=1)
    for j in range(1,10):
        d.line([(0,H*j/10),(W,H*j/10)],fill=(0,120,255),width=1)
    c.save(f'/tmp/{name}.png'); print(name,(x1,y1,x2,y2))
crop('rmaxRCT',700,330,1020,660,4)
